        "code": "def forward(groups):\n    date, spaces, time = groups\n    dt = datetime.strptime(f'2023-{date} {time}', '%Y-%m-%d %H:%M:%S.%f')\n    return {'stored': [int(dt.timestamp() * 1000000)], 'layout': [len(spaces)]}\n\ndef inverse(record):\n    micros = int(record['stored'][0])\n    dt = datetime.fromtimestamp(micros / 1000000)\n    spaces = ' ' * record['layout'][0]\n    return f\"{dt.strftime('%m-%d')}{spaces}{dt.strftime('%H:%M:%S.%f')[:-3]}\""
      }
